pub fn authored_name_at(
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    node: Rc<Node>,
) -> String {
    match node.ident_span.clone() {
        Some(span) => match v1_rt::map_get(&source_indices, span.file.clone()) {
            Some(index) => {
                let text = source_text_at(index.clone(), span.clone());
                if (text.clone() == "".to_string()) {
                    "".to_string()
                } else {
                    text.clone()
                }
            }
            None => {
                if ((v1_rt::string_length(&span.file.clone()) > 8)
                    && (v1_rt::substring(&span.file.clone(), 0, 8) == "<kernel:".to_string()))
                {
                    v1_rt::substring(
                        &span.file.clone(),
                        8,
                        (v1_rt::string_length(&span.file.clone()) - 1),
                    )
                } else {
                    node.name.clone()
                }
            }
        },
        None => "".to_string(),
    }
}

pub fn find_child_named(
    n: Rc<Node>,
    name: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Option<Rc<Node>> {
    match Rc::new({
        let mut __result = Vec::new();
        for c in n.children.clone().iter().cloned() {
            if (authored_name_at(source_indices.clone(), c.clone()) == name.clone()) {
                __result.push(c);
            }
        }
        __result
    })
    .first()
    .cloned()
    {
        Some(ch) => Some(ch.clone()),
        None => None,
    }
}

pub fn has_child_named(
    n: Rc<Node>,
    name: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    {
        let mut __found = false;
        for c in n.children.clone().iter().cloned() {
            if (authored_name_at(source_indices.clone(), c.clone()) == name.clone()) {
                __found = true;
                break;
            }
        }
        __found
    }
}

