pub fn make_field_node(
    name: String,
    type_expr: Rc<Node>,
    cardinality: Cardinality,
    default_value: Option<Rc<Node>>,
    from_key: Option<String>,
    span: Rc<SourceSpan>,
    name_span: Rc<SourceSpan>,
) -> Rc<Node> {
    {
        let children = match default_value.clone() {
            Some(dv) => Rc::new(vec![type_expr.clone(), dv.clone()]),
            None => Rc::new(vec![type_expr.clone()]),
        };
        let props = match from_key.clone() {
            Some(fk) => Rc::new(vec![make_field_init_node(
                "from_key".to_string(),
                Rc::new(Node {
                    name: fk.clone(),
                    span: no_span(),
                    ident_span: default_ident_span(fk.clone(), no_span()),
                    children: Rc::new(vec![]),
                    connective: Rc::new(Connective::NoConnective),
                    params: Rc::new(vec![]),
                    inferred: None,
                    return_cardinality: Cardinality::Required,
                    uses: Rc::new(vec![]),
                    body: None,
                    transport: None,
                    properties: Rc::new(vec![]),
                    type_annotation: None,
                    is_self_recursive: false,
                    has_non_tail_self_call: false,
                    match_pattern: None,
                    expr_data: Rc::new(ExprData::NoExprData),
                }),
                no_span(),
                no_span(),
            )]),
            None => Rc::new(vec![]),
        };
        Rc::new(Node {
            name: name.clone(),
            span: span.clone(),
            ident_span: default_ident_span(name.clone(), name_span.clone()),
            children: children.clone(),
            connective: Rc::new(Connective::NoConnective),
            params: Rc::new(vec![]),
            inferred: None,
            return_cardinality: cardinality.clone(),
            uses: Rc::new(vec![]),
            body: None,
            transport: None,
            properties: v1_rt::concat(props.clone(), type_expr.properties.clone()),
            type_annotation: None,
            is_self_recursive: false,
            has_non_tail_self_call: false,
            match_pattern: None,
            expr_data: Rc::new(ExprData::NoExprData),
        })
    }
}

