pub fn map_children(node: Rc<Node>, transform: impl Fn(Rc<Node>) -> Rc<Node> + Clone) -> Rc<Node> {
    Rc::new(Node {
        name: node.name.clone(),
        ident: node.ident.clone(),
        span: node.span.clone(),
        ident_span: node.ident_span.clone(),
        children: Rc::new({
            let mut __result = Vec::new();
            for child in node.children.clone().iter().cloned() {
                __result.push(transform(child.clone()));
            }
            __result
        }),
        connective: node.connective.clone(),
        params: node.params.clone(),
        inferred: node.inferred.clone(),
        return_cardinality: node.return_cardinality.clone(),
        uses: node.uses.clone(),
        body: node.body.clone(),
        transport: node.transport.clone(),
        properties: node.properties.clone(),
        type_annotation: node.type_annotation.clone(),
        is_self_recursive: node.is_self_recursive.clone(),
        has_non_tail_self_call: node.has_non_tail_self_call.clone(),
        match_pattern: node.match_pattern.clone(),
        expr_data: node.expr_data.clone(),
    })
}

pub fn expr_has_self_call(
    texpr: Rc<Node>,
    fn_name: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*texpr.expr_data.clone()).clone() {
            ExprData::ExprCall { .. } => {
                if (expr_call_func_at(texpr.clone(), source_indices.clone()) == fn_name.clone()) {
                    true
                } else {
                    {
                        let mut __found = false;
                        for child in texpr.children.clone().iter().cloned() {
                            if expr_has_self_call(
                                child.clone(),
                                fn_name.clone(),
                                source_indices.clone(),
                            ) {
                                __found = true;
                                break;
                            }
                        }
                        __found
                    }
                }
            }
            _ => {
                let mut __found = false;
                for child in texpr.children.clone().iter().cloned() {
                    if expr_has_self_call(child.clone(), fn_name.clone(), source_indices.clone()) {
                        __found = true;
                        break;
                    }
                }
                __found
            }
        }
    })
}

pub fn expr_has_non_tail_self_call(
    texpr: Rc<Node>,
    fn_name: String,
    in_tail: bool,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*texpr.expr_data.clone()).clone() {
            ExprData::ExprCall { .. } => {
                if (expr_call_func_at(texpr.clone(), source_indices.clone()) == fn_name.clone()) {
                    if (in_tail.clone() == false) {
                        true
                    } else {
                        {
                            let mut __found = false;
                            for child in texpr.children.clone().iter().cloned() {
                                if expr_has_non_tail_self_call(
                                    child.clone(),
                                    fn_name.clone(),
                                    false,
                                    source_indices.clone(),
                                ) {
                                    __found = true;
                                    break;
                                }
                            }
                            __found
                        }
                    }
                } else {
                    {
                        let mut __found = false;
                        for child in texpr.children.clone().iter().cloned() {
                            if expr_has_non_tail_self_call(
                                child.clone(),
                                fn_name.clone(),
                                false,
                                source_indices.clone(),
                            ) {
                                __found = true;
                                break;
                            }
                        }
                        __found
                    }
                }
            }
            ExprData::ExprError { .. } => false,
            ExprData::ExprVar {
                binding_kind: _, ..
            } => false,
            ExprData::ExprLiteral { value: _, .. } => false,
            ExprData::ExprFieldAccess { summary: _, .. } => {
                let mut __found = false;
                for child in texpr.children.clone().iter().cloned() {
                    if expr_has_non_tail_self_call(
                        child.clone(),
                        fn_name.clone(),
                        false,
                        source_indices.clone(),
                    ) {
                        __found = true;
                        break;
                    }
                }
                __found
            }
            ExprData::ExprMethodCall {
                method_semantics: _,
                ..
            } => {
                let mut __found = false;
                for child in texpr.children.clone().iter().cloned() {
                    if expr_has_non_tail_self_call(
                        child.clone(),
                        fn_name.clone(),
                        false,
                        source_indices.clone(),
                    ) {
                        __found = true;
                        break;
                    }
                }
                __found
            }
            ExprData::ExprIf => {
                let cond_bad = expr_has_non_tail_self_call(
                    if_condition(texpr.clone()),
                    fn_name.clone(),
                    false,
                    source_indices.clone(),
                );
                let then_bad = expr_has_non_tail_self_call(
                    if_then_branch(texpr.clone()),
                    fn_name.clone(),
                    in_tail.clone(),
                    source_indices.clone(),
                );
                let else_bad = match if_else_branch(texpr.clone()) {
                    Some(e) => expr_has_non_tail_self_call(
                        e.clone(),
                        fn_name.clone(),
                        in_tail.clone(),
                        source_indices.clone(),
                    ),
                    None => false,
                };
                ((cond_bad.clone() || then_bad.clone()) || else_bad.clone())
            }
            ExprData::ExprMatch => {
                let scrut_bad = expr_has_non_tail_self_call(
                    match_scrutinee(texpr.clone()),
                    fn_name.clone(),
                    false,
                    source_indices.clone(),
                );
                let arms_bad = {
                    let mut __found = false;
                    for arm_node in match_arm_nodes(texpr.clone()).iter().cloned() {
                        if expr_has_non_tail_self_call(
                            arm_body(arm_node.clone()),
                            fn_name.clone(),
                            in_tail.clone(),
                            source_indices.clone(),
                        ) {
                            __found = true;
                            break;
                        }
                    }
                    __found
                };
                (scrut_bad.clone() || arms_bad.clone())
            }
            ExprData::ExprLet => {
                let val_bad = expr_has_non_tail_self_call(
                    let_value(texpr.clone()),
                    fn_name.clone(),
                    false,
                    source_indices.clone(),
                );
                let body_bad = match let_body(texpr.clone()) {
                    Some(b) => expr_has_non_tail_self_call(
                        b.clone(),
                        fn_name.clone(),
                        in_tail.clone(),
                        source_indices.clone(),
                    ),
                    None => false,
                };
                (val_bad.clone() || body_bad.clone())
            }
            ExprData::ExprBlock => {
                let ss = texpr.children.clone();
                let ss_count = (ss.clone().len() as i64);
                if (ss_count.clone() == 0) {
                    false
                } else {
                    {
                        let init_bad = {
                            let mut __found = false;
                            for p in Rc::new({
                                let mut __result = Vec::new();
                                for p in Rc::new(
                                    ss.clone()
                                        .iter()
                                        .cloned()
                                        .enumerate()
                                        .map(|(i, v)| (i as i64, v))
                                        .collect::<Vec<_>>(),
                                )
                                .iter()
                                .cloned()
                                {
                                    if (p.0.clone() < (ss_count.clone() - 1)) {
                                        __result.push(p);
                                    }
                                }
                                __result
                            })
                            .iter()
                            .cloned()
                            {
                                if expr_has_non_tail_self_call(
                                    p.1.clone(),
                                    fn_name.clone(),
                                    false,
                                    source_indices.clone(),
                                ) {
                                    __found = true;
                                    break;
                                }
                            }
                            __found
                        };
                        let last_bad = match ss.clone().last().cloned() {
                            Some(last_expr) => expr_has_non_tail_self_call(
                                last_expr.clone(),
                                fn_name.clone(),
                                in_tail.clone(),
                                source_indices.clone(),
                            ),
                            None => false,
                        };
                        (init_bad.clone() || last_bad.clone())
                    }
                }
            }
            ExprData::ExprReturn => {
                let mut __found = false;
                for child in texpr.children.clone().iter().cloned() {
                    if expr_has_non_tail_self_call(
                        child.clone(),
                        fn_name.clone(),
                        true,
                        source_indices.clone(),
                    ) {
                        __found = true;
                        break;
                    }
                }
                __found
            }
            ExprData::NoExprData => {
                let mut __found = false;
                for child in texpr.children.clone().iter().cloned() {
                    if expr_has_non_tail_self_call(
                        child.clone(),
                        fn_name.clone(),
                        in_tail.clone(),
                        source_indices.clone(),
                    ) {
                        __found = true;
                        break;
                    }
                }
                __found
            }
            _ => {
                let mut __found = false;
                for child in texpr.children.clone().iter().cloned() {
                    if expr_has_non_tail_self_call(
                        child.clone(),
                        fn_name.clone(),
                        false,
                        source_indices.clone(),
                    ) {
                        __found = true;
                        break;
                    }
                }
                __found
            }
        }
    })
}

pub fn service_config_properties(
    endpoint: Rc<Node>,
    auth: Option<Rc<Node>>,
    auth_input: Option<Rc<Node>>,
    auth_source: Option<Rc<Node>>,
    rate_limit: Option<Rc<Node>>,
    retry: Option<Rc<Node>>,
) -> Rc<Vec<Rc<Node>>> {
    {
        let zero_span = no_span();
        let ep_prop = Rc::new(vec![make_field_init_node(
            "svc_endpoint".to_string(),
            endpoint.clone(),
            zero_span.clone(),
            zero_span.clone(),
        )]);
        let auth_prop = match auth.clone() {
            Some(a) => Rc::new(vec![make_field_init_node(
                "svc_auth".to_string(),
                a.clone(),
                zero_span.clone(),
                zero_span.clone(),
            )]),
            None => Rc::new(vec![]),
        };
        let auth_input_prop = match auth_input.clone() {
            Some(ai) => Rc::new(vec![make_field_init_node(
                "svc_auth_input".to_string(),
                ai.clone(),
                zero_span.clone(),
                zero_span.clone(),
            )]),
            None => Rc::new(vec![]),
        };
        let auth_source_prop = match auth_source.clone() {
            Some(src) => Rc::new(vec![make_field_init_node(
                "svc_auth_source".to_string(),
                src.clone(),
                zero_span.clone(),
                zero_span.clone(),
            )]),
            None => Rc::new(vec![]),
        };
        let rate_prop = match rate_limit.clone() {
            Some(r) => Rc::new(vec![make_field_init_node(
                "svc_rate_limit".to_string(),
                r.clone(),
                zero_span.clone(),
                zero_span.clone(),
            )]),
            None => Rc::new(vec![]),
        };
        let retry_prop = match retry.clone() {
            Some(r) => Rc::new(vec![make_field_init_node(
                "svc_retry".to_string(),
                r.clone(),
                zero_span.clone(),
                zero_span.clone(),
            )]),
            None => Rc::new(vec![]),
        };
        v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(ep_prop.clone(), auth_prop.clone()),
                        auth_input_prop.clone(),
                    ),
                    auth_source_prop.clone(),
                ),
                rate_prop.clone(),
            ),
            retry_prop.clone(),
        )
    }
}

