pub fn import_node(
    module_path: String,
    is_all: bool,
    specific_names: Rc<Vec<Rc<Node>>>,
    span: Rc<SourceSpan>,
    name_span: Rc<SourceSpan>,
) -> Rc<Node> {
    {
        let wildcard_marker = if is_all.clone() {
            Some(Rc::new(Node {
                name: "".to_string(),
                span: span.clone(),
                ident_span: None,
                children: Rc::new(vec![]),
                connective: Rc::new(Connective::NoConnective),
                params: Rc::new(vec![]),
                inferred: None,
                return_cardinality: Cardinality::Required,
                uses: Rc::new(vec![]),
                body: None,
                transport: None,
                properties: Rc::new(vec![]),
                type_annotation: None,
                is_self_recursive: false,
                has_non_tail_self_call: false,
                match_pattern: None,
                expr_data: Rc::new(ExprData::NoExprData),
            }))
        } else {
            None
        };
        Rc::new(Node {
            name: module_path.clone(),
            span: span.clone(),
            ident_span: Some(name_span.clone()),
            children: specific_names.clone(),
            connective: Rc::new(Connective::NoConnective),
            params: Rc::new(vec![]),
            inferred: None,
            return_cardinality: Cardinality::Required,
            uses: Rc::new(vec![]),
            body: wildcard_marker.clone(),
            transport: None,
            properties: Rc::new(vec![]),
            type_annotation: None,
            is_self_recursive: false,
            has_non_tail_self_call: false,
            match_pattern: None,
            expr_data: Rc::new(ExprData::NoExprData),
        })
    }
}

pub fn import_is_all(n: Rc<Node>) -> bool {
    (n.body.clone() != None)
}

pub fn import_specific_names_at(
    n: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Vec<String>> {
    Rc::new({
        let mut __result = Vec::new();
        for c in n.children.clone().iter().cloned() {
            __result.push(authored_name_at(source_indices.clone(), c.clone()));
        }
        __result
    })
}

